#include <iostream>
#include <vector>
using namespace std;

// O(1) - Thời gian hằng số: không phụ thuộc kích thước mảng
int layPhanTuDau(const vector<int>& a) {
    return a[0];
}

// O(log n) - Logarit: tìm kiếm nhị phân, mỗi bước bỏ đi một nửa
int binarySearch(const vector<int>& a, int x) {
    int trai = 0, phai = (int)a.size() - 1;
    while (trai <= phai) {
        int giua = trai + (phai - trai) / 2;
        if (a[giua] == x) return giua;
        if (a[giua] < x) trai = giua + 1;
        else phai = giua - 1;
    }
    return -1;
}

// O(n) - Tuyến tính: duyệt mảng một lần
int timMax(const vector<int>& a) {
    int lonNhat = a[0];
    for (int x : a) if (x > lonNhat) lonNhat = x;
    return lonNhat;
}

// O(n²) - Bậc hai: hai vòng lặp lồng nhau
int demCapTongBangK(const vector<int>& a, int k) {
    int dem = 0;
    for (size_t i = 0; i < a.size(); i++)
        for (size_t j = i + 1; j < a.size(); j++)
            if (a[i] + a[j] == k) dem++;
    return dem;
}

// O(2ⁿ) - Hàm mũ: mỗi lần gọi tách thành 2 lần gọi (Fibonacci đệ quy ngây thơ)
long long fib(int n) {
    return n <= 1 ? n : fib(n - 1) + fib(n - 2);
}

// Bộ nhớ O(n): tạo thêm một mảng cùng kích thước
vector<int> nhanDoi(const vector<int>& a) {
    vector<int> kq;
    kq.reserve(a.size());
    for (int x : a) kq.push_back(x * 2);
    return kq;
}


